// ============================================================================
// PENROSE OUTCOME TAIL - THE script. ALL data and logic live here.
// Editing any outcome in any of the six trees = editing ONE entry in OUTCOMES.
// Inputs:  outcome_key (preferred)  OR  source_tree + suggested_outcome (legacy)
// Outputs: outcome_screen_html + source_netting_html (transforms);
//          suggested_outcome, outcome_title, suggested_outcome_text,
//          outcome_found, alt_* staging for the swap script (form data)
// ============================================================================

// ---------------- DATA: outcome catalog (edit outcomes HERE) ----------------
// entry: { code, title, sug, html, src, variant?, alt? }
// variant "p1_adult"/"p1_child" marks Pharmacy First referral outcomes;
// alt names the fallback entry the swap script applies (refused / age 0-4).
var OUTCOMES = {
 "con_email_prescription": {
  "code": "1.website",
  "html": "<p style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 1rem; color: rgb(65, 65, 65); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\" id=\"isPasted\"><span style=\"color: rgb(255, 0, 0); font-size: 24px; font-family: Tahoma, Geneva, sans-serif;\">This outcome is for patients who have been seen by Pharmacy First and require a follow-up appointment. If the patient was refused a consultation, send Claire the name of the Pharmacy and the reason for refusal</span></p><p style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 1rem; color: rgb(65, 65, 65); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\" id=\"isPasted\"></p><p></p><p><br></p>",
  "src": "contraception",
  "sug": "Contraception &nbsp;suggested outcome: 1. Patient should email about prescription / fill in prescription form on surgery&#39;s website",
  "title": "Outcome: Email prescription"
 },
 "con_msi_choices": {
