 "wh_advice": {
  "code": "1.noappt",
  "html": "<p id=\"isPasted\"></p><p></p><p><br></p><p><span style=\"font-size: 18px; font-family: Tahoma, Geneva, sans-serif;\">\u2747\ufe0f <span style=\"color: rgb(0, 0, 0);\"><u>Register with a midwife</u></span></span></p><ul><li><span style=\"font-size: 18px; font-family: Tahoma, Geneva, sans-serif; color: rgb(0, 0, 0);\">GSTT - <a href=\"https://www.smartsurvey.co.uk/s/GSTTMaternityReferral/\" title=\"\" target=\"_blank\" rel=\"noopener noreferrer\">https://www.smartsurvey.co.uk/s/GSTTMaternityReferral/</a></span></li><li><span style=\"font-size: 18px; font-family: Tahoma, Geneva, sans-serif; color: rgb(0, 0, 0);\">UHL - As soon as you think or know you are pregnant contact either Lewisham Direct Access to Midwives service on 075 5411 5649 or email <a href=\"mailto:LewishamMidwives@nhs.net\" title=\"\">LewishamMidwives@nhs.net</a></span></li><li><span style=\"font-size: 18px; font-family: Tahoma, Geneva, sans-serif; color: rgb(0, 0, 0);\">KCH - <a href=\"https://www.kch.nhs.uk/maternity/book-your-maternity-care-with-us/\" title=\"\" target=\"_blank\" rel=\"noopener noreferrer\">https://www.kch.nhs.uk/maternity/book-your-maternity-care-with-us/</a></span></li><li><span style=\"font-size: 18px; font-family: Tahoma, Geneva, sans-serif; color: rgb(0, 0, 0);\">General info -&nbsp;</span><span style=\"color: rgb(0, 0, 0);\"><a href=\"https://www.nhs.uk/service-search/other-health-services/maternity-services\" title=\"\" target=\"_blank\" rel=\"noopener noreferrer\"><span style=\"font-size: 18px; font-family: Tahoma, Geneva, sans-serif;\">https://www.nhs.uk/service-search/other-health-services/maternity-services</span></a></span></li></ul><p><br></p><p><span style=\"font-size: 18px; color: rgb(41, 105, 176); font-family: Tahoma, Geneva, sans-serif;\" id=\"isPasted\">If you suspect a safeguarding concern, book GP same-day F2F. If no capacity, speak with Duty Doctor on site.</span></p><div class=\"zt-accordion\"><details class=\"zt-ac-block\"><summary class=\"zt-ac-title\"><h3><strong><span style=\"color: rgb(0, 0, 0);\">Duty Doctor template</span></strong></h3></summary><div class=\"zt-ac-body-container\"><div class=\"zt-ac-body\"><div id=\"isPasted\"><p><strong><span style=\"color: rgb(0, 0, 0);\">Request</span></strong><span style=\"color: rgb(0, 0, 0);\">&nbsp;- one line stating what is requested of the Duty Doctor</span></p><p><span style=\"color: rgb(0, 0, 0);\"><strong>Symptom</strong> - issue / problem patient called for</span></p><p><span style=\"color: rgb(0, 0, 0);\"><strong>Zingtree information</strong></span></p><ul><li style=\"color: rgb(0, 0, 0);\"><u>Current symptoms</u> - anything that was \"ticked\" on Zingtree, list these in bullet point</li><li style=\"color: rgb(0, 0, 0);\"><u>Duration</u> - state how long patient has been experiencing symptoms (if relevant)</li><li style=\"color: rgb(0, 0, 0);\"><u>Treatment trialled</u> - state any OTC or previous treatments the patient has tried (if relevant - from patient or recent EMIS consultation notes)</li><li style=\"color: rgb(0, 0, 0);\"><u>Timeframe</u> of suggested outcome listed on ZT if DD not first option - same day, within 24 hours etc</li><li style=\"color: rgb(0, 0, 0);\"><u>Clinicians</u> listed on ZT if DD not first option - state why these were not chosen</li></ul><p><span style=\"color: rgb(0, 0, 0);\"><br></span></p><p><span style=\"color: rgb(255, 0, 0);\"><strong>Example</strong></span></p><ul><li style=\"color: rgb(0, 0, 0);\">Management of high blood pressure with no symptoms</li><li style=\"color: rgb(0, 0, 0);\">Patient blood pressure recorded at home 200/100</li><li style=\"color: rgb(0, 0, 0);\">Patient does not have regular medication for their blood pressure</li><li style=\"color: rgb(0, 0, 0);\">Zingtree outcome suggests:</li></ul><ol><li style=\"color: rgb(0, 0, 0);\">GP same-day, F2F</li><li style=\"color: rgb(0, 0, 0);\">Duty doctor list</li></ol><ul><li data-list-indent=\"1\" data-list-type=\"bulleted\" style=\"margin-left: 32px; color: rgb(0, 0, 0);\"><p>No GP same day appt, therefore added to DD list</p></li></ul></div></div></div></details></div><p><br></p><p><br></p>",
  "src": "womens_health",
  "sug": "Women's Health &nbsp;suggested outcome: 1. Advise patient to perform a pregnancy test at home and give advice on how to self-register with a midwife",
  "title": "Outcome: Advice"
 },
 "wh_contact_abortion_clinic": {
  "code": "1.contactservice, Accurx | 2.GPsdF2F | 3.GPEA | 4.UCC",
  "html": "<div data-v-37e0392a=\"\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px; color: rgb(54, 54, 54); font-family: &quot;Open Sans&quot;; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(254, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div data-v-37e0392a=\"\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px 15px; margin: 0px; position: relative; min-height: 1px; float: left; width: 1170px;\"><div data-v-2b27a37b=\"\" data-v-37e0392a=\"\" data-test-id=\"zt-content-canvas-136\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px;\"><div data-v-2b27a37b=\"\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: -12px; display: flex; flex-wrap: wrap; flex: 1 1 auto;\"><div data-v-2b27a37b=\"\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 12px; margin: 0px; width: 1164px; flex-basis: 0px; flex-grow: 1; max-width: 100%;\"><div data-v-2b27a37b=\"\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin-top: 0px !important; margin-right: -12px; margin-bottom: -12px; margin-left: -12px; display: flex; flex-wrap: wrap; flex: 1 1 auto;\"><div data-v-2b27a37b=\"\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding-top: 12px; padding-right: 0px !important; padding-bottom: 12px; padding-left: 12px; margin: 0px; width: 1164px; flex-basis: 0px; flex-grow: 1; max-width: 100%;\"><span data-v-f2ad0da0=\"\" data-v-2b27a37b=\"\" data-test=\"html-only-0\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px; text-align: left !important;\"><p style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px 0px 12px;\"><span style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px; font-size: 24px; font-family: Tahoma, Geneva, sans-serif;\">Patient's who have had abortions will need to first contact the abortion clinic to discuss any issues. <em style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px;\">(They are better placed to manage the post-abortion period).</em></span></p><ul style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px 0px 0px 40px; margin: 0px 0px 12px;\"><li style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px; font-size: 24px; font-family: Tahoma, Geneva, sans-serif;\">They can also seek advice and support via an MSI <span style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px;\"><span style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px;\"><span style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px;\">Reproductive Choices&nbsp;</span></span></span>clinic if they prefer. &nbsp;S<span style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px;\"><span style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px;\"><span style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px;\">end patient a link via Accurx to MSI website:&nbsp;</span></span></span><span style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px; font-size: 24px; font-family: Tahoma, Geneva, sans-serif;\"><span style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px;\"><a href=\"https://www.msichoices.org.uk/contact-us/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px; color: rgb(197, 86, 86); font-weight: 600; text-decoration: none; background-color: transparent;\">https://www.msichoices.org.uk/contact-us/</a></span></span></li></ul><p style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px 0px 12px;\"><span style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px; font-family: Tahoma, Geneva, sans-serif; color: rgb(226, 80, 65); font-size: 24px;\">If safeguarding concern suspected, book <strong style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px; font-weight: bolder;\">GP same-day F2F</strong>. If no capacity, add to Duty Doctor list.</span></p></span></div></div></div></div></div></div></div><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p id=\"isPasted\"></p><p></p><p><br></p><div class=\"zt-accordion\"><details class=\"zt-ac-block\"><summary class=\"zt-ac-title\"><h3><strong><span style=\"color: rgb(0, 0, 0);\">Duty Doctor template</span></strong></h3></summary><div class=\"zt-ac-body-container\"><div class=\"zt-ac-body\"><div id=\"isPasted\"><p><strong><span style=\"color: rgb(0, 0, 0);\">Request</span></strong><span style=\"color: rgb(0, 0, 0);\">&nbsp;- one line stating what is requested of the Duty Doctor</span></p><p><span style=\"color: rgb(0, 0, 0);\"><strong>Symptom</strong> - issue / problem patient called for</span></p><p><span style=\"color: rgb(0, 0, 0);\"><strong>Zingtree information</strong></span></p><ul><li style=\"color: rgb(0, 0, 0);\"><u>Current symptoms</u> - anything that was \"ticked\" on Zingtree, list these in bullet point</li><li style=\"color: rgb(0, 0, 0);\"><u>Duration</u> - state how long patient has been experiencing symptoms (if relevant)</li><li style=\"color: rgb(0, 0, 0);\"><u>Treatment trialled</u> - state any OTC or previous treatments the patient has tried (if relevant - from patient or recent EMIS consultation notes)</li><li style=\"color: rgb(0, 0, 0);\"><u>Timeframe</u> of suggested outcome listed on ZT if DD not first option - same day, within 24 hours etc</li><li style=\"color: rgb(0, 0, 0);\"><u>Clinicians</u> listed on ZT if DD not first option - state why these were not chosen</li></ul><p><span style=\"color: rgb(0, 0, 0);\"><br></span></p><p><span style=\"color: rgb(255, 0, 0);\"><strong>Example</strong></span></p><ul><li style=\"color: rgb(0, 0, 0);\">Management of high blood pressure with no symptoms</li><li style=\"color: rgb(0, 0, 0);\">Patient blood pressure recorded at home 200/100</li><li style=\"color: rgb(0, 0, 0);\">Patient does not have regular medication for their blood pressure</li><li style=\"color: rgb(0, 0, 0);\">Zingtree outcome suggests:</li></ul><ol><li style=\"color: rgb(0, 0, 0);\">GP same-day, F2F</li><li style=\"color: rgb(0, 0, 0);\">Duty doctor list</li></ol><ul><li data-list-indent=\"1\" data-list-type=\"bulleted\" style=\"margin-left: 32px; color: rgb(0, 0, 0);\"><p>No GP same day appt, therefore added to DD list</p></li></ul></div></div></div></details></div><p><br></p><p><br></p>",
  "src": "womens_health",
  "sug": "Women's Health &nbsp;suggested outcome: 1. Advise patient to contact Abortion Clinic 2. GP, same day, F2F 3. GPEA / GP hub 4. Advise patient to visit Urgent Care Centre",
  "title": "Outcome: Contact Abortion Clinic"
 },
 "wh_contact_abortion_clinic_2": {
  "code": "1.contactservice, Accurx | 2.discuss",
  "html": "<div data-v-37e0392a=\"\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px; color: rgb(54, 54, 54); font-family: &quot;Open Sans&quot;; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(254, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><div data-v-37e0392a=\"\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px 15px; margin: 0px; position: relative; min-height: 1px; float: left; width: 1170px;\"><div data-v-2b27a37b=\"\" data-v-37e0392a=\"\" data-test-id=\"zt-content-canvas-136\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px;\"><div data-v-2b27a37b=\"\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: -12px; display: flex; flex-wrap: wrap; flex: 1 1 auto;\"><div data-v-2b27a37b=\"\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 12px; margin: 0px; width: 1164px; flex-basis: 0px; flex-grow: 1; max-width: 100%;\"><div data-v-2b27a37b=\"\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin-top: 0px !important; margin-right: -12px; margin-bottom: -12px; margin-left: -12px; display: flex; flex-wrap: wrap; flex: 1 1 auto;\"><div data-v-2b27a37b=\"\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding-top: 12px; padding-right: 0px !important; padding-bottom: 12px; padding-left: 12px; margin: 0px; width: 1164px; flex-basis: 0px; flex-grow: 1; max-width: 100%;\"><span data-v-f2ad0da0=\"\" data-v-2b27a37b=\"\" data-test=\"html-only-0\" style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px; text-align: left !important;\"><p style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px 0px 12px;\"><span style=\"font-size: 24px; font-family: Tahoma, Geneva, sans-serif;\">When patient is still pregnant one week after abortion, it is advised that they contact the clinic where the abortion was performed.</span></p><p style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px 0px 12px;\"><span style=\"font-size: 24px; font-family: Tahoma, Geneva, sans-serif;\">If patient unable to attend abortion clinic, seek Clinical Oversight.</span></p><p style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px 0px 12px;\"><span style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px; font-family: Tahoma, Geneva, sans-serif; color: rgb(226, 80, 65); font-size: 24px;\">If you suspect a safeguarding concern, book <strong style=\"box-sizing: inherit; background-repeat: no-repeat; padding: 0px; margin: 0px; font-weight: bolder;\">GP same-day F2F</strong>. If no capacity, add to Duty Doctor list.</span></p></span></div></div></div></div></div></div></div><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p id=\"isPasted\"></p><p></p><div class=\"zt-accordion\"><details class=\"zt-ac-block\"><summary class=\"zt-ac-title\"><h3><strong><span style=\"color: rgb(0, 0, 0);\">Duty Doctor template</span></strong></h3></summary><div class=\"zt-ac-body-container\"><div class=\"zt-ac-body\"><div id=\"isPasted\"><p><strong><span style=\"color: rgb(0, 0, 0);\">Request</span></strong><span style=\"color: rgb(0, 0, 0);\">&nbsp;- one line stating what is requested of the Duty Doctor</span></p><p><span style=\"color: rgb(0, 0, 0);\"><strong>Symptom</strong> - issue / problem patient called for</span></p><p><span style=\"color: rgb(0, 0, 0);\"><strong>Zingtree information</strong></span></p><ul><li style=\"color: rgb(0, 0, 0);\"><u>Current symptoms</u> - anything that was \"ticked\" on Zingtree, list these in bullet point</li><li style=\"color: rgb(0, 0, 0);\"><u>Duration</u> - state how long patient has been experiencing symptoms (if relevant)</li><li style=\"color: rgb(0, 0, 0);\"><u>Treatment trialled</u> - state any OTC or previous treatments the patient has tried (if relevant - from patient or recent EMIS consultation notes)</li><li style=\"color: rgb(0, 0, 0);\"><u>Timeframe</u> of suggested outcome listed on ZT if DD not first option - same day, within 24 hours etc</li><li style=\"color: rgb(0, 0, 0);\"><u>Clinicians</u> listed on ZT if DD not first option - state why these were not chosen</li></ul><p><span style=\"color: rgb(255, 0, 0);\"><strong>Example</strong></span></p><ul><li style=\"color: rgb(0, 0, 0);\">Management of high blood pressure with no symptoms</li><li style=\"color: rgb(0, 0, 0);\">Patient blood pressure recorded at home 200/100</li><li style=\"color: rgb(0, 0, 0);\">Patient does not have regular medication for their blood pressure</li><li style=\"color: rgb(0, 0, 0);\">Zingtree outcome suggests:</li></ul><ol><li style=\"color: rgb(0, 0, 0);\">GP same-day, F2F</li><li style=\"color: rgb(0, 0, 0);\">Duty doctor list</li></ol><ul><li data-list-indent=\"1\" data-list-type=\"bulleted\" style=\"margin-left: 32px; color: rgb(0, 0, 0);\"><p>No GP same day appt, therefore added to DD list</p></li></ul></div></div></div></details></div><p><br></p><p><br></p>",
