 },
 "wh_emergency": {
  "code": "1.AEor999",
  "html": "<p style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 1rem; color: rgb(65, 65, 65); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\" id=\"isPasted\"><span style=\"color: rgb(255, 0, 0); font-size: 24px;\">Ask Clinical Oversight for permission before advising A&amp;E. If no response in 30 mins, ask Claire or Karan.</span></p><p id=\"isPasted\"></p><p></p><p><br></p><p><span style=\"font-size: 18px; color: rgb(41, 105, 176); font-family: Tahoma, Geneva, sans-serif;\" id=\"isPasted\">If you suspect a safeguarding concern, <strong>also&nbsp;</strong>make a note of the concerns in a hidden consultation and alert the Care Coordinator at site</span></p><p><br></p>",
